import openpyxl
from xlsxwriter.utility import xl_col_to_name as col
from process_model import ROOT, DATA, PRODUCTS, ELEMENTS, block_row, reference_result

h = None


def line(ws, row, label, expression, unit='', style='calc'):
    h.write(ws, f'A{row}', label)
    h.formula(ws, f'B{row}', expression, style)
    if unit: h.write(ws,f'C{row}',unit,'muted')


def takt():
    ws=h.setup('Время такта','07 / ЛИСТ ВЫЧИСЛЕНИЯ ВРЕМЕНИ ТАКТА','E')
    ws.set_column('A:A',6);ws.set_column('B:B',74);ws.set_column('C:C',20);ws.set_column('D:D',18);ws.set_column('E:E',62)
    h.metadata(ws,'E')
    h.headers(ws,7,['Код','Вопрос бланка ФЦК','Результат','Единица','Расчёт / пояснение'])
    rows=[('A','Сколько секунд в смене?',"=IF(ISNUMBER('Ввод'!B17),'Ввод'!B17*60,\"\")",'с', 'Длительность смены × 60; не умножать на количество сотрудников.'),
          ('B','Сколько секунд уходит на регламентные перерывы?',"=IF(COUNT('Ввод'!B18:B21)=4,SUM('Ввод'!B18:B21)*60,\"\")",'с','Обед + прочие перерывы + фиксированная подготовка/завершение. Санобработка отдельно.'),
          ('C','Сколько рабочих секунд в смене (A − B)?',"='Ввод'!B27",'с','Фонд одной последовательной ячейки.'),
          ('D','Общее число изделий всех типов за смену',"='Ввод'!B28",'партий','Единица процесса — одна загрузка SOLIA. Сумма целых партий всех 18 видов, а не килограммы.'),
          ('E','Время такта (C / D)',"='Ввод'!B30",'с/партию','Такт по всему ассортименту, согласно разделу 7.2 и приложению 1 МУ-41-2024.')]
    for r,(code,q,expr,unit,note) in enumerate(rows,8):
        h.write(ws,f'A{r}',code,'subhead');h.write(ws,f'B{r}',q);h.formula(ws,f'C{r}',expr,'total');h.write(ws,f'D{r}',unit,'muted');h.write(ws,f'E{r}',note);ws.set_row(r-1,62)
    h.merge(ws,'A15:E17','Заказчик в модели — следующий производственный передел. На выходе: промытая продукция в чистой таре «СО» или «ЗЕЛЕНЬ». При нулевом спросе такт не определяется (пустое значение и сообщение в «Контроль»), а не принимается равным нулю.','warning')
    h.merge(ws,'A19:E21','Расчётная единица выбрана по аналогии с загрузкой/плавкой из приложения 1. Если на предприятии применяется иная единица учёта, сначала согласуйте единицу и пересчитайте спрос, а не смешивайте кг и партии в одной формуле.','muted')
    ws.print_area('A1:E21')


def observations():
    ws=h.setup('Лист наблюдений','08 / ПОДГОТОВИТЕЛЬНЫЙ ЛИСТ НАБЛЮДЕНИЯ','F')
    ws.set_column('A:A',7);ws.set_column('B:B',17);ws.set_column('C:C',13);ws.set_column('D:D',41);ws.set_column('E:E',9);ws.set_column('F:F',62)
    h.metadata(ws,'F')
    h.headers(ws,7,['№ замера','Время цикла, с','Учтён (1/0)','Причина / условия','Элемент','Список рабочих элементов и переходов'])
    for j in range(10):
        r=8+j;c=col(4+j)
        h.write(ws,f'A{r}',j+1)
        h.formula(ws,f'B{r}','='+h.selected(c,16))
        h.formula(ws,f'C{r}','=IF(ISNUMBER('+h.selected(c,17)+'),1,0)','calc_int')
        h.formula(ws,f'D{r}','='+h.selected(c,4),'calc_text')
        h.write(ws,f'E{r}',j+1 if ELEMENTS[j]['kind']=='Ручная' else '—')
        h.write(ws,f'F{r}',ELEMENTS[j]['name']);ws.set_row(r-1,42)
    h.write(ws,'E18','—');h.write(ws,'F18',ELEMENTS[10]['name'])
    for r,label,expr,unit in [
        (20,'T min, с',h.selected('O',17),''),(21,'T max, с',h.selected('P',17),''),
        (22,'Размах цикла, с',h.selected('Q',17),''),
        (23,'Колебания / T min',f'IF(AND(ISNUMBER(B20),B20>0),B22/B20,"")','%'),
        (24,'Среднее, с',h.selected('U',17),''),(25,'Учтено циклов',h.selected('T',17),''),
        (26,'Такт, с/партию',"'Ввод'!B30",'')]:
        h.merge(ws,f'C{r}:F{r}',label);h.formula(ws,f'B{r}','='+expr,'pct' if unit=='%' else 'total')
    h.merge(ws,'A28:F30','Наблюдения выше — представление выбранного продукта и сценария из «Ввод». Все 18 наборов хранятся в «Замеры ДО» и «Замеры ЦЕЛЬ». Изменяйте жёлтые исходные клетки там. Флаг 0 или неполный цикл исключает всю колонку из статистики; требуется не менее 10 полных сопоставимых замеров.','warning')
    ws.print_area('A1:F30')


def manual():
    ws=h.setup('Ручная работа','09 / ЛИСТ НАБЛЮДЕНИЯ РУЧНОЙ РАБОТЫ','S',a3=True)
    ws.set_column('A:A',5);ws.set_column('B:B',38);ws.set_column('C:C',28);ws.set_column('D:M',8);ws.set_column('N:R',12);ws.set_column('S:S',34)
    h.metadata(ws,'S')
    h.headers(ws,7,['№','Рабочий элемент','Точка отсчёта']+[str(x) for x in range(1,11)]+['t min, с','t max − min, с','Рег. секунды','t отрег., с','Колебания, с','Комментарий'])
    for i,e in enumerate(ELEMENTS):
        r=8+i;offset=5+i
        h.write(ws,f'A{r}',i+1 if e['kind']=='Ручная' else '—');h.write(ws,f'B{r}',e['name']);h.write(ws,f'C{r}',e['endpoint'])
        for j in range(10):h.formula(ws,f'{col(3+j)}{r}','='+h.selected(col(4+j),offset))
        for out,src in [('N','O'),('O','Q'),('P','R'),('Q','S'),('R','T')]:h.formula(ws,f'{out}{r}','='+h.selected(src,offset))
        h.write(ws,f'S{r}','Регулировка допустима' if e['kind']=='Ручная' else 'Не распределять регулировочные секунды на переходы, ожидание и потери.','muted');ws.set_row(r-1,46)
    h.write(ws,'B20','ИТОГО','subhead')
    for c in ['N','O','P','Q','R']:h.formula(ws,f'{c}20',f'=IF(COUNT({c}8:{c}18)=11,SUM({c}8:{c}18),"")','total')
    notes=[('T — минимальное время полного учтённого цикла',h.selected('O',17)),
           ('T − Σt min — время регулировки',h.selected('R',17)),
           ('Сумма размахов элементов, не относящихся к потерям',h.selected('S',17)),
           ('Контроль: Σt отрег − T (должно быть 0)',h.selected('V',17))]
    for r,(label,expr) in enumerate(notes,22):h.merge(ws,f'C{r}:M{r}',label);h.formula(ws,f'N{r}','='+expr,'total')
    h.merge(ws,'A27:S29','МУ-41-2024, стр. 17: регулировка распределяется пропорционально размахам элементов, не относящихся к потерям. В модели это необходимые ручные действия, включая обязательный контроль. На переходы и ожидания регулировка не назначается. Если размахи допустимых элементов нулевые, остаток относится к самому длительному допустимому элементу.','muted')
    ws.print_area('A1:S29')


def map_sheet():
    ws=h.setup('Карта СР','10 / КАРТА СТАНДАРТИЗИРОВАННОЙ РАБОТЫ','J',a3=True)
    h.metadata(ws,'J');ws.set_column('A:A',7);ws.set_column('B:B',37);ws.set_column('C:F',13);ws.set_column('G:H',16);ws.set_column('I:J',33)
    h.headers(ws,7,['Точка','Место / действие','X ДО, м','Y ДО, м','X ЦЕЛЬ, м','Y ЦЕЛЬ, м','Путь ДО, м','Путь ЦЕЛЬ, м','Особое внимание','Периодичность контроля'])
    points=[('1. Осмотр / подготовка',0,0,0,0,'Качество: упаковка, отсутствие порчи','Каждая партия'),
            ('2. Взвешивание',2,0,1,0,'Качество: масса не выше предела','Каждая загрузка'),
            ('3. SOLIA',4,0,2,0,'Безопасность: программа; полная остановка перед доступом по паспорту','Каждый цикл; санобработка после 4'),
            ('4. Чистая тара / контроль',4,3,2,2,'Качество: чистая маркированная тара','Каждая партия'),
            ('5. Передача годной продукции',2,3,1,2,'Не допускать перекрёстного загрязнения','Каждая партия'),
            ('6. Возврат к началу (пунктир в натурной карте)',0,0,0,0,'Возврат не является транспортировкой сырья','Каждый цикл')]
    for r,p in enumerate(points,8):
        h.write(ws,f'A{r}',r-7);h.write(ws,f'B{r}',p[0])
        for j,v in enumerate(p[1:5]):h.inp(ws,f'{col(2+j)}{r}',v,'ДЕМО: координата точки в метрах. Замените по планировке. Прямые отрезки — иллюстрация; реальные препятствия и разделение потоков учитываются в натурной карте.',validation=h.decimal(-1000,1000))
        for out,x,y in [('G','C','D'),('H','E','F')]:
            h.formula(ws,f'{out}{r}', '=0' if r==8 else f'=IF(COUNT({x}{r-1}:{y}{r})=4,SQRT(({x}{r}-{x}{r-1})^2+({y}{r}-{y}{r-1})^2),"")')
        h.write(ws,f'I{r}',p[5]);h.write(ws,f'J{r}',p[6]);ws.set_row(r-1,56)
    h.write(ws,'B15','Длина замкнутого маршрута','subhead')
    for c in ['G','H']:h.formula(ws,f'{c}15',f'=IF(COUNT({c}8:{c}13)=6,SUM({c}8:{c}13),"")','total')
    for state,x,y,anchor,color in [('ДО','C','D','A18','#2789A7'),('ЦЕЛЬ','E','F','F18','#24966D')]:
        chart=h.BOOK.add_chart({'type':'scatter','subtype':'straight_with_markers'})
        # Forward route + separate dashed return, as in the methodology.
        chart.add_series({'name':'1 → 2 → 3 → 4 → 5','categories':f"='Карта СР'!${x}$8:${x}$12",'values':f"='Карта СР'!${y}$8:${y}$12",'line':{'color':color,'width':2},'marker':{'type':'circle','size':6}})
        chart.add_series({'name':'5 ⇢ 1: возврат','categories':f"='Карта СР'!${x}$12:${x}$13",'values':f"='Карта СР'!${y}$12:${y}$13",'line':{'color':color,'dash_type':'dash'},'marker':{'type':'none'}})
        chart.set_title({'name':f'{state} · условный эскиз; не обмер помещения'})
        chart.set_x_axis({'name':'X, м','major_gridlines':{'visible':True}});chart.set_y_axis({'name':'Y, м','major_gridlines':{'visible':True}})
        chart.set_size({'width':560,'height':330});chart.set_legend({'position':'bottom'});ws.insert_chart(anchor,chart)
    h.merge(ws,'A34:J36','Порядок движения задан номерами 1→2→3→4→5; возврат — пунктиром. Контроль качества и точки безопасности приведены в таблице. После изменения координат графики и длины пересчитаются, но времена переходов НЕ масштабируются по расстоянию: их нужно повторно измерить.','warning')
    h.write(ws,'B38','Проект стандартного запаса в процессе');h.formula(ws,'G38','=IF(\'Ввод\'!B28>0,1,0)','calc_int');h.write(ws,'H38','партия максимум')
    h.write(ws,'B39','Масса партии в SOLIA');h.formula(ws,'G39','='+h.selected_cat('I'));h.write(ws,'H39','кг')
    h.write(ws,'B40','Межоперационный буфер в последовательной схеме');h.write(ws,'G40',0,'source_num');h.write(ws,'H40','партий')
    h.merge(ws,'A42:J44','Принят поток одной партии: в момент мойки в машине находится 1 партия; дополнительных межоперационных заделов не предусмотрено. Это проектная схема, не расчёт запасов по закону Литтла и не разрешение на хранение скоропортящейся продукции. Сырьё до первой операции и готовая продукция после последней не относятся к стандартному запасу (МУ, стр. 4, 47–50).','muted')
    ws.print_area('A1:J44')


def capacity():
    ws=h.setup('Производственная способность','11 / ЛИСТ ПРОИЗВОДСТВЕННОЙ СПОСОБНОСТИ ОБОРУДОВАНИЯ','R',a3=True)
    ws.set_column('B:B',29);ws.set_column('C:C',14);ws.set_column('D:Q',13);ws.set_column('R:R',35);ws.set_column('S:Z',None,None,{'hidden':True})
    h.merge(ws,'A5:R5','Одна SOLIA: загрузка/выгрузка не перекрывают автоматическую программу. Пределы ниже относятся к машине без внешней подготовки сырья; выполнимость всего потока — в «Расчет ДО/ЦЕЛЬ».','subhead')
    h.headers(ws,7,['№','Операция / продукт','Машина','Ручная у машины ДО, с','Авто, с','Цикл машины ДО, с','Санобработка каждые N','Комплекс санобработки, с','Способность ДО, партий*','Цикл машины ЦЕЛЬ, с','Способность ЦЕЛЬ, партий*','План партий','Занятость ДО, с/смену**','Занятость ЦЕЛЬ, с/смену**','Доля ресурса ДО','Доля ресурса ЦЕЛЬ','План / способность ДО','Примечание'])
    for i,p in enumerate(PRODUCTS):
        r=8+i;b=block_row(i);s=b+5
        h.write(ws,f'A{r}',i+1);h.write(ws,f'B{r}',p['name']);h.write(ws,f'C{r}','SOLIA','source')
        exprs={'D':f"IF(COUNT('Замеры ДО'!S{s+4},'Замеры ДО'!S{s+6})=2,'Замеры ДО'!S{s+4}+'Замеры ДО'!S{s+6},\"\")", 'E':f"'Ассортимент'!R{r}", 'F':f'IF(COUNT(D{r}:E{r})=2,D{r}+E{r},"")', 'G':"'Ввод'!B24", 'H':"IF(COUNT('Периодическая работа'!H8:H12)=5,SUM('Периодическая работа'!H8:H12),\"\")", 'J':f"'Расчет ЦЕЛЬ'!R{r}", 'L':f"'Ассортимент'!O{r}",
               'M':f'IF(AND(ISNUMBER(L{r}),ISNUMBER(\'Ввод\'!B28),\'Ввод\'!B28>0,ISNUMBER(F{r}),ISNUMBER(J{r})),L{r}*F{r}+L{r}/\'Ввод\'!B28*SUM(\'Периодическая работа\'!P8:P12),IF(L{r}=0,0,""))',
               'N':f'IF(AND(ISNUMBER(L{r}),ISNUMBER(\'Ввод\'!B28),\'Ввод\'!B28>0,ISNUMBER(F{r}),ISNUMBER(J{r})),L{r}*J{r}+L{r}/\'Ввод\'!B28*SUM(\'Периодическая работа\'!Q8:Q12),IF(L{r}=0,0,""))',
               'O':f'IF(AND(ISNUMBER(\'Ввод\'!B27),\'Ввод\'!B27>0,ISNUMBER(M{r})),M{r}/\'Ввод\'!B27,"")',
               'P':f'IF(AND(ISNUMBER(\'Ввод\'!B27),\'Ввод\'!B27>0,ISNUMBER(N{r})),N{r}/\'Ввод\'!B27,"")',
               'Q':f'IF(AND(ISNUMBER(I{r}),I{r}>0,ISNUMBER(L{r})),L{r}/I{r},"")'}
        for c,e in exprs.items():h.formula(ws,f'{c}{r}','='+e,'pct' if c in ['O','P','Q'] else 'calc')
        # Exact monoproduct capacity, including a nonzero initial counter and final partial block.
        for cyc,qc,remc,out in [('F','S','T','I'),('J','U','V','K')]:
            gate=f'AND(ISNUMBER(\'Ввод\'!B27),\'Ввод\'!B27>0,ISNUMBER({cyc}{r}),{cyc}{r}>0,ISNUMBER(H{r}),H{r}>0,ISNUMBER(\'Ввод\'!B25))'
            h.formula(ws,f'{qc}{r}',f'=IF({gate},INT((\'Ввод\'!B27+\'Ввод\'!B25*{cyc}{r})/(4*{cyc}{r}+H{r})),"")')
            h.formula(ws,f'{remc}{r}',f'=IF(ISNUMBER({qc}{r}),\'Ввод\'!B27+\'Ввод\'!B25*{cyc}{r}-{qc}{r}*(4*{cyc}{r}+H{r}),"")')
            h.formula(ws,f'{out}{r}',f'=IF({gate},MAX(0,4*{qc}{r}+MAX(0,MIN(3,INT(({remc}{r}-IF(\'Ввод\'!B26=1,H{r},0))/{cyc}{r})))-\'Ввод\'!B25),"")','calc_int')
        h.write(ws,f'R{r}','* Если всю смену мыть только этот продукт. Не суммировать мощности разных продуктов.','muted');ws.set_row(r-1,54)
    h.write(ws,'B27','Общая загрузка одной машины','subhead')
    for c in ['M','N','O','P']:h.formula(ws,f'{c}27',f'=IF(COUNT({c}8:{c}25)=18,SUM({c}8:{c}25),"")','pct' if c in ['O','P'] else 'total')
    h.merge(ws,'A29:R31','** Санобработка — общий ресурс для смешанного плана. В строках её сменное время распределено пропорционально партиям исключительно для аналитики; фактическое число событий рассчитано один раз на «Периодическая работа». Суммировать способности I/K нельзя: это одна и та же машина в разных сценариях монопродуктового выпуска.','warning')
    for r,label,expr in [(33,'Доступно машин',"'Ввод'!B22"),(34,'Нижняя потребность ДО, ед.',"'Расчет ДО'!B43"),(35,'Нижняя потребность ЦЕЛЬ, ед.',"'Расчет ЦЕЛЬ'!B43")]:h.merge(ws,f'C{r}:H{r}',label);h.formula(ws,f'B{r}','='+expr,'total')
    h.merge(ws,'A37:R39','При нескольких машинах целые партии, порядок санобработки каждой машины и занятость сотрудников надо распределить по реальному графику. Агрегированная оценка не гарантирует выполнение плана. Для принятой схемы 1 машина + 1 оператор проверяйте также средний цикл, а не только лучшие времена.','muted')
    ws.print_area('A1:R39')


def combined(state):
    name=f'ОТ {state}';ws=h.setup(name,f'12 / ОБЪЕДИНЁННАЯ ТАБЛИЦА СТАНДАРТИЗИРОВАННОЙ РАБОТЫ · {state}','AS',a3=True)
    ws.set_column('A:A',5);ws.set_column('B:B',45);ws.set_column('C:H',12);ws.set_column('I:I',23);ws.set_column('J:AS',2.7)
    h.metadata(ws,'AS')
    h.merge(ws,'A6:F6','Масштаб = максимум (такт; время цикла × 1,05) / 36 клеток','muted')
    h.formula(ws,'G6',f'=IF(AND(ISNUMBER({h.selected("O",17,state)}),ISNUMBER(\'Ввод\'!B30)),MAX(\'Ввод\'!B30,({h.selected("O",17,state)})*1.05)/36,1)')
    h.write(ws,'H6','с / клетку','muted')
    h.headers(ws,8,['№','Рабочий элемент','Ручная, с','Авто, с','Ожидание, с','Переход, с','Начало, с','Конец, с','Исполнитель / ресурс'])
    for j in range(36):h.formula(ws,f'{col(9+j)}8',f'={j}*$G$6','calc_int')
    for i,e in enumerate(ELEMENTS):
        r=9+i;kind=e['kind'];dur=h.selected('S',5+i,state)
        h.write(ws,f'A{r}',i+1 if kind=='Ручная' else '—');h.write(ws,f'B{r}',e['name']);h.write(ws,f'I{r}','SOLIA + оператор (ожидание)' if kind=='Авто/ожидание' else 'Оператор №1')
        for out,match in [('C','Ручная'),('D','Авто/ожидание'),('F','Переход')]:h.formula(ws,f'{out}{r}','='+dur if kind==match else '=0')
        h.formula(ws,f'E{r}','='+dur if kind in ['Авто/ожидание','Потери'] else '=0')
        h.formula(ws,f'G{r}','=0' if i==0 else f'=H{r-1}')
        h.formula(ws,f'H{r}',f'=IF(COUNT(C{r}:G{r})=5,G{r}+C{r}+F{r}+MAX(D{r},E{r}),"")')
        style={'Ручная':'manual','Переход':'walk','Авто/ожидание':'auto','Потери':'wait'}[kind]
