def build_reports(helper):
    global h
    h=helper
    takt();observations();manual();map_sheet();capacity();combined('ДО');combined('ЦЕЛЬ');diagram()
    improvements();improvement_report();sop();sanitation_sop();plan();quality();sop_check();metrics();controls();sources();training();start()


def weighted_element(indices,state):
    terms=[]
    for i in range(len(PRODUCTS)):
        r=8+i;b=block_row(i)+5
        values=','.join(f"'Замеры {state}'!S{b+e}" for e in indices)
        terms.append(f"'Ассортимент'!O{r}*SUM({values})")
    return f'IF(AND(ISNUMBER(\'Ввод\'!B28),\'Ввод\'!B28>0,COUNTIF(\'Расчет {state}\'!U8:U25,"НЕТ ЗАМЕРОВ")=0),('+ '+'.join(terms)+')/\'Ввод\'!B28,"")'


